window.AUTH=window.AUTH||{};window.AUTH["24-1056"]={"d":"24-1056","id":"2025/24-1056","n":"Rico v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Isabel Rico","date":"2025-08-14","url":"https://www.supremecourt.gov/DocketPDF/24/24-1056/369734/20250814143948147_24-1056%20Rico%20TS%20Br.%208.14.25%20pdfA.pdf","side":"pet","n":96},{"k":"respondent","label":"Brief of respondent United States","date":"2025-09-15","url":"https://www.supremecourt.gov/DocketPDF/24/24-1056/374687/20250915154205683_24-1056%20--%20Rico%20v.%20U.S.%20with%20appendix.pdf","side":"res","n":76},{"k":"reply","label":"Reply of petitioner Isabel Rico","date":"2025-10-15","url":"https://www.supremecourt.gov/DocketPDF/24/24-1056/379723/20251015151306443_24-1056%20Rico%20Reply%20Br.%2010.15.25%20pdfA.pdf","side":"pet","n":31}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/607us2r23_4g15.pdf","tr":true,"items":[{"t":"case","label":"Anderson v. Corall","cite":"263 U.S. 193","y":1923,"id":"scdb/1923-028","sc":1,"by":{"0":"23-25","1":"4, 14, 26, 27, 30, 33","2":"19"},"q":[{"src":"brief","b":0,"text":"[m]ere lapse of time without imprisonment or other restraint contemplated by the law does not constitute service of sentence.","cite":"263 U.S. 193, 196"},{"src":"brief","b":1,"text":"[m]ere lapse of time without imprisonment or other restraint contemplated by the law does not constitute service of sentence.","cite":"263 U.S. 193, 196"},{"src":"argument","who":"Mr. Handell","text":"So they couldn't quite be tethered to a violation of supervision in the way that, you know, this Court treated -- treated the interruption in Anderson versus Corall and Zerbst versus Kidwell."}]},{"t":"case","label":"Artis v. District of Columbia","cite":"583 U.S. 71","y":2018,"id":"2017/16-460","sc":1,"by":{"0":"15"}},{"t":"case","label":"Beck v. Prupis","cite":"529 U.S. 494","y":2000,"id":"1999/98-1480","sc":1,"by":{"0":"36"}},{"t":"case","label":"Bittner v. United States","cite":"598 U.S. 85","y":2023,"id":"2022/21-1195","sc":1,"by":{"0":"47"},"q":[{"src":"brief","b":0,"text":"an individual ‘is not to be subjected to a penalty unless the words of the statute plainly impose it.’","cite":"598 U.S. 85, 102"}]},{"t":"case","label":"Bowles v. Russell","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"by":{"0":"22","1":"39"}},{"t":"case","label":"Bradley v. United States","cite":"410 U.S. 605","y":1973,"id":"1972/71-1304","sc":1,"by":{"0":"4"}},{"t":"case","label":"Caballery v. United States Parole Commission","cite":"673 F.2d 43","y":1982,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/673/43/","by":{"0":"38-39","1":"28, 33","2":"20"},"q":[{"src":"brief","b":1,"text":"tolling a parolee’s sentence for the period during which he is in abscondence does not ‘extend’ or increase the original sentence. It merely incorporates the common law rule that lapse of time does not constitute service of sentence and, hence, stops the sentence from running for that period during which the offender, through some fault of his own, has failed to serve his sentence.","cite":"673 F.2d 43, 46"}]},{"t":"case","label":"Carter v. United States","cite":"530 U.S. 255","y":2000,"id":"1999/99-5716","sc":1,"by":{"0":"34-35","1":"34"},"q":[{"src":"brief","b":0,"text":"applies only when Congress makes use of a statutory term with established meaning at common law.","cite":"530 U.S. 255, 264"},{"src":"brief","b":0,"text":"Congress simply describes an offense analogous to a common-law crime without using common-law terms.","cite":"530 U.S. at 265"},{"src":"brief","b":1,"text":"presumption * * * ‘applies only when Congress makes use of a statutory term with established meaning at common law.’","cite":"530 U.S. 255, 264"}]},{"t":"case","label":"City & County of San Francisco v. EPA","cite":"145 S. Ct. 704","y":2025,"id":"2024/23-753","sc":1,"by":{"0":"21"}},{"t":"case","label":"Commissioner v. Acker","cite":"361 U.S. 87","y":1959,"id":"1959/13","sc":1,"by":{"0":"47"}},{"t":"case","label":"Esteras v. United States","cite":"145 S. Ct. 2031","y":2025,"id":"2024/23-7483","sc":1,"by":{"0":"4, 19, 42-43","1":"5, 30"},"q":[{"src":"brief","b":0,"text":"a component of a defendant’s prison sentence.","cite":"145 S. Ct. 2031, 2039 n.4"},{"src":"brief","b":0,"text":"by contrast, ‘is not a punishment in lieu of incarceration.’","cite":"145 S. Ct. at 2041"},{"src":"brief","b":1,"text":"component of a defendant’s prison sentence,","cite":"145 S. Ct. 2031, 2039 n.4"},{"src":"brief","b":1,"text":"a term of supervised release is not itself a ‘sentence’ at all; it is a component of a defendant’s prison sentence.","cite":"145 S. Ct. 2031, 2039 n.4"},{"src":"argument","who":"Justice Alito","text":"Well, I was just going to ask whether you think that -- that the Petitioner's argument is inconsistent with or at least in tension with our decision last term in Esteras, which discussed the factors that are relevant in deciding whether to revoke supervised release and what to do if supervised release is revoked."},{"src":"argument","who":"Mr. Handell","text":"I agree, Justice Alito, and I think that what this Court said in Esteras is that courts at a supervised release revocation hearing can and should take into account all of the forward-looking interests that -- that criminal sentences serve, which includes deterrence, incapacitation, things like that."}]},{"t":"case","label":"Evans v. United States","cite":"504 U.S. 255","y":1992,"id":"1991/90-6105","sc":1,"by":{"0":"35"}},{"t":"case","label":"Gozlon-Peretz v. United States","cite":"498 U.S. 395","y":1991,"id":"1990/89-7370","sc":1,"by":{"0":"42","1":"45"}},{"t":"case","label":"Harmelin v. Michigan","cite":"501 U.S. 957","y":1991,"id":"1990/89-7272","sc":1,"by":{"0":"34"},"q":[{"src":"brief","b":0,"text":"no common-law punishments in the federal system.","cite":"501 U.S. 957, 975"}]},{"t":"case","label":"Henrique v. United States Marshal","cite":"476 F. Supp. 618","y":1979,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./476/618/","by":{"0":"39"}},{"t":"case","label":"Holguin-Hernandez v. United States","cite":"589 U.S. 169","y":2020,"id":"2019/18-7739","sc":1,"by":{"0":"5"}},{"t":"case","label":"Isbrandtsen Co. v. Johnson","cite":"343 U.S. 779","y":1952,"id":"scdb/1951-093","sc":1,"by":{"0":"36"}},{"t":"case","label":"Jama v. ICE","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"by":{"0":"31"}},{"t":"case","label":"Johnson v. United States","cite":"529 U.S. 694","y":2000,"id":"1999/99-5153","sc":1,"by":{"0":"4","1":"3, 7, 12, 16, 17, 32, 36, 45"},"q":[{"src":"brief","b":0,"text":"a form of postconfinement monitoring overseen by the sentencing court.","cite":"529 U.S. 694, 696-97"},{"src":"brief","b":0,"text":"‘fulfills rehabilitative ends’ and ‘provides individuals with postconfinement assistance.’","cite":"529 U.S. at 59"},{"src":"brief","b":1,"text":"a form of postconfinement monitoring overseen by the sentencing court,","cite":"529 U.S. 694, 697"},{"src":"brief","b":1,"text":"giving full effect to the lawful judgment previously imposed on the defendant.","cite":"529 U.S. at 59"}]},{"t":"case","label":"Kemp v. United States","cite":"596 U.S. 528","y":2022,"id":"2021/21-5726","sc":1,"by":{"0":"36"},"q":[{"src":"brief","b":0,"text":"meaning was well-settled before the transplantation.","cite":"596 U.S. 528, 539"}]},{"t":"case","label":"Kousisis v. United States","cite":"145 S. Ct. 1382","y":2025,"id":"2024/23-909","sc":1,"by":{"0":"36"}},{"t":"case","label":"Molina-Martinez v. United States","cite":"578 U.S. 189","y":2016,"id":"2015/14-8913","sc":1,"by":{"0":"51"}},{"t":"case","label":"Mont v. United States","cite":"587 U.S. 514","y":2019,"id":"2018/17-8995","sc":1,"by":{"0":"22, 26","1":"7, 13, 17, 18, 23, 29, 31, 38, 39, 47","2":"8"},"q":[{"src":"brief","b":1,"text":"[s]upervised release has no statutory function until confinement ends.","cite":"587 U.S. at 523"}]},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"by":{"0":"35"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"by":{"0":"35"}},{"t":"case","label":"Nicholas v. United States","cite":"527 F.2d 1160","y":1976,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/527/1160/","by":{"0":"40-41","1":"28, 34","2":"21"},"q":[{"src":"brief","b":2,"text":"cannot credit . . . probationary time","cite":"527 F.2d 1160"}]},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"0":"33"}},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"by":{"0":"41"}},{"t":"case","label":"Tennessee v. Davis","cite":"100 U.S. 257","y":1880,"id":"scdb/1879-096","sc":1,"by":{"0":"18"}},{"t":"case","label":"United States v. Bailey","cite":"444 U.S. 394","y":1980,"id":"1979/78-990","sc":1,"by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"while [the defendant] remained at large.","cite":"444 U.S. 394, 414 n.10"}]},{"t":"case","label":"United States v. Barinas","cite":"865 F.3d 99","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/865/99/","by":{"0":"44"}},{"t":"case","label":"United States v. Buchanan","cite":"638 F.3d 448","y":2011,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/638/448/","by":{"0":"6, 44","1":"7, 46"},"q":[{"src":"brief","b":1,"text":"case[s] where a defendant absconds late in the release term and his absence is not detected in time for a warrant or summons to be issued before the term expires.","cite":"638 F.3d 448, 456 n.7"}]},{"t":"case","label":"United States v. Cartagena-Lopez","cite":"979 F.3d 356","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/979/356/","by":{"0":"44"},"q":[{"src":"brief","b":0,"text":"the principle that defendants should not benefit from their own wrongdoing.","cite":"979 F.3d 356, 362"}]},{"t":"case","label":"United States v. Davis","cite":"588 U.S. 445","y":2019,"id":"2018/18-431","sc":1,"by":{"0":"47"},"q":[{"src":"brief","b":0,"text":"fair notice of the law ‘and on the plain principle that the power of punishment is vested in the legislative, not in the judicial department.’","cite":"588 U.S. 445, 464-65"}]},{"t":"case","label":"United States v. Fisher","cite":"895 F.2d 208","y":1990,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/895/208/","by":{"0":"40"}},{"t":"case","label":"United States v. Granderson","cite":"511 U.S. 39","y":1994,"id":"1993/92-1662","sc":1,"by":{"0":"42-43"},"q":[{"src":"brief","b":0,"text":"is not a punishment in lieu of incarceration.","cite":"511 U.S. 39, 50"}]},{"t":"case","label":"United States v. Gulley","cite":"130 F.4th 1178","y":2025,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/130/1178/","by":{"0":"22"}},{"t":"case","label":"United States v. Hansen","cite":"599 U.S. 762","y":2023,"id":"2022/22-179","sc":1,"by":{"0":"34"},"q":[{"src":"brief","b":0,"text":"[w]hen Congress transplants a common-law term, the old soil comes with it.","cite":"599 U.S. 762, 778"}]},{"t":"case","label":"United States v. Haymond","cite":"588 U.S. 634","y":2019,"id":"2018/17-1672","sc":1,"by":{"0":"16"}},{"t":"case","label":"United States v. Hernández-Ferrer","cite":"599 F.3d 63","y":2010,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/599/63/","by":{"0":"46"}},{"t":"case","label":"United States v. Island","cite":"916 F.3d 249","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/916/249/","by":{"0":"47-48, 50","1":"18"},"q":[{"src":"brief","b":1,"text":"A supervising court cannot offer postconfinement assistance or ensure compliance with the terms of release while a defendant is truant.","cite":"916 F.3d 249, 253"}]},{"t":"case","label":"United States v. Janvier","cite":"599 F.3d 264","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/599/264/","by":{"0":"6, 21","1":"39"},"q":[{"src":"argument","who":"Mr. Handell","text":"But, in terms of, you know, what I think 3583(i) was -- was going after, I mean, as I think Petitioner acknowledged on page 6 of her opening brief and as the Second Circuit recognized in the Janvier case, this was really about a very narrow subset of late-breaking violations where there was not time left on the clock for the district court to conduct the -- the revocation hearing required by Rule 32.1."}]},{"t":"case","label":"United States v. Johnson","cite":"529 U.S. 53","y":2000,"id":"1999/98-1696","sc":1,"by":{"0":"4, 20, 42-43, 50","1":"3, 12, 13, 16-18, 37, 45, 48","2":"8, 10"},"q":[{"src":"brief","b":0,"text":"fulfill[] rehabilitative ends, distinct from those served by incarceration.","cite":"529 U.S. 53, 59"},{"src":"brief","b":0,"text":"‘fulfills rehabilitative ends’ and ‘provides individuals with postconfinement assistance.’","cite":"529 U.S. at 59"},{"src":"brief","b":1,"text":"giving full effect to the lawful judgment previously imposed on the defendant.","cite":"529 U.S. at 59"},{"src":"brief","b":1,"text":"[t]o say [a defendant] was released while still imprisoned diminishes the concept the word intends to convey,","cite":"529 U.S. at 57"},{"src":"brief","b":2,"text":"[t]he proper inference . . . is that Congress considered the issue of exceptions and, in the end, limited the statute to the ones set forth.","cite":"529 U.S. at 58"}]},{"t":"case","label":"United States v. Lancer","cite":"508 F.2d 719","y":1975,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/508/719/","by":{"0":"40","1":"29","2":"21"}},{"t":"case","label":"United States v. Murguia-Oliveros","cite":"421 F.3d 951","y":2005,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/421/951/","by":{"0":"48"},"q":[{"src":"brief","b":0,"text":"merely by failing to comply with the terms of his supervised release.","cite":"421 F.3d 951, 953"}]},{"t":"case","label":"United States v. Quality Stores, Inc.","cite":"572 U.S. 141","y":2014,"id":"2013/12-1408","sc":1,"by":{"0":"29"}},{"t":"case","label":"United States v. Santos","cite":"553 U.S. 507","y":2008,"id":"2007/06-1005","sc":1,"by":{"0":"18"}},{"t":"case","label":"United States v. Swick","cite":"137 F.4th 336","y":2025,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/137/336/","by":{"0":"31, 33, 40, 48-49","1":"15, 44, 46, 47"},"q":[{"src":"brief","b":1,"text":"sentenced to 33 months in prison, to run concurrently with longer state sentences, and two years of supervised release.","cite":"137 F.4th at 338"},{"src":"brief","b":1,"text":"commit[ing] a slew of state crimes","cite":"137 F.4th at 338"},{"src":"argument","who":"Mr. Unikowsky","text":"So that is the facts of the Swick case, which is currently pending on certiorari to this Court. As far as I know, that's the only time that's come up since 1984."},{"src":"argument","who":"Mr. Unikowsky","text":"Yes, Swick from the Fifth Circuit, Your Honor."},{"src":"argument","who":"Mr. Handell","text":"So I think, as has been discussed, we have the Swick case out of the Fifth Circuit, where a defendant was serving a state term of imprisonment and then did not report to her federal probation officer as she was directed."}]},{"t":"case","label":"x United States v. Talley","cite":"83 F.4th 1296","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/83/1296/","by":{"0":"16-17, 24, 26, 41-42, 45-46"},"q":[{"src":"brief","b":0,"text":"[t]he idea is that a person should not be credited with serving a prison sentence if he is not, in fact, in prison.","cite":"83 F.4th at 1301"},{"src":"brief","b":0,"text":"should be clear, it need not be express.","cite":"83 F.4th at 1304"}]},{"t":"case","label":"United States v. Texas","cite":"507 U.S. 529","y":2003,"id":"1992/91-1729","sc":1,"by":{"0":"36","2":"18"}},{"t":"case","label":"United States v. Turley","cite":"352 U.S. 407","y":1957,"id":"1956/289","sc":1,"by":{"0":"35"}},{"t":"case","label":"Van Buren v. United States","cite":"593 U.S. 374","y":2021,"id":"2020/19-783","sc":1,"by":{"0":"35"}},{"t":"case","label":"Yegiazaryan v. Smagin","cite":"599 U.S. 533","y":2023,"id":"2022/22-381","sc":1,"by":{"0":"36"}},{"t":"case","label":"Zerbst v. Kidwell","cite":"304 U.S. 359","y":1938,"id":"scdb/1937-051","sc":1,"by":{"0":"25","1":"27, 32","2":"19"},"q":[{"src":"argument","who":"Mr. Handell","text":"So they couldn't quite be tethered to a violation of supervision in the way that, you know, this Court treated -- treated the interruption in Anderson versus Corall and Zerbst versus Kidwell."}]},{"t":"usc","label":"18 U.S.C. § 3290","url":"https://www.law.cornell.edu/uscode/text/18/3290","stext":{"head":"§3290. Fugitives from justice","paras":[[0,"No statute of limitations shall extend to any person fleeing from justice."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3290?type=usc&year=mostrecent&link-type=html"},"by":{"0":"23","2":"13"}},{"t":"usc","label":"18 U.S.C. § 3551","url":"https://www.law.cornell.edu/uscode/text/18/3551","stext":{"head":"§3551. Authorized sentences","paras":[[0,"(a) In General.—Except as otherwise specifically provided, a defendant who has been found guilty of an offense described in any Federal statute, including sections 13 and 1153 of this title, other than an Act of Congress applicable exclusively in the District of Columbia or the Uniform Code of Military Justice, shall be sentenced in accordance with the provisions of this chapter so as to achieve the purposes set forth in subparagraphs (A) through (D) of section 3553(a)(2) to the extent that they are applicable in light of all the circumstances of the case."],[0,"(b) Individuals.—An individual found guilty of an offense shall be sentenced, in accordance with the provisions of section 3553, to—"],[1,"(1) a term of probation as authorized by subchapter B;"],[1,"(2) a fine as authorized by subchapter C; or"],[1,"(3) a term of imprisonment as authorized by subchapter D."],[0,"A sentence to pay a fine may be imposed in addition to any other sentence. A sanction authorized by section 3554, 3555, or 3556 may be imposed in addition to the sentence required by this subsection."],[0,"(c) Organizations.—An organization found guilty of an offense shall be sentenced, in accordance with the provisions of section 3553, to—"],[1,"(1) a term of probation as authorized by subchapter B; or"],[1,"(2) a fine as authorized by subchapter C."],[0,"A sentence to pay a fine may be imposed in addition to a sentence to probation. A sanction authorized by section 3554, 3555, or 3556 may be imposed in addition to the sentence required by this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3551?type=usc&year=mostrecent&link-type=html"},"by":{"0":"30","1":"3"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(a)(1)"],"by":{"0":"46, 46"}},{"t":"usc","label":"18 U.S.C. § 3561","url":"https://www.law.cornell.edu/uscode/text/18/3561","subs":["(a)"],"by":{"0":"32"}},{"t":"usc","label":"18 U.S.C. § 3563","url":"https://www.law.cornell.edu/uscode/text/18/3563","by":{"0":"32"}},{"t":"usc","label":"18 U.S.C. § 3565","url":"https://www.law.cornell.edu/uscode/text/18/3565","subs":["(c)"],"by":{"0":"41"}},{"t":"usc","label":"18 U.S.C. § 3583","url":"https://www.law.cornell.edu/uscode/text/18/3583","subs":["(b)","(b)(1)","(b)(2)","(b)(3)","(c)","(d)","(e)","(e)(1)","(e)(2)","(e)(3)","(g)","(h)","(i)","(j)","(k)","(a)"],"stext":{"head":"§3583. Inclusion of a term of supervised release after imprisonment","paras":[[0,"(a) In General.—The court, in imposing a sentence to a term of imprisonment for a felony or a misdemeanor, may include as a part of the sentence a requirement that the defendant be placed on a term of supervised release after imprisonment, except that the court shall include as a part of the sentence a requirement that the defendant be placed on a term of supervised release if such a term is required by statute or if the defendant has been convicted for the first time of a domestic violence crime as defined in section 3561(b)."],[0,"(b) Authorized Terms of Supervised Release.—Except as otherwise provided, the authorized terms of supervised release are—"],[1,"(1) for a Class A or Class B felony, not more than five years;"],[1,"(2) for a Class C or Class D felony, not more than three years; and"],[1,"(3) for a Class E felony, or for a misdemeanor (other than a petty offense), not more than one year."],[0,"(c) Factors To Be Considered in Including a Term of Supervised Release.—The court, in determining whether to include a term of supervised release, and, if a term of supervised release is to be included, in determining the length of the term and the conditions of supervised release, shall consider the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)."],[0,"(d) Conditions of Supervised Release.—The court shall order, as an explicit condition of supervised release, that the defendant not commit another Federal, State, or local crime during the term of supervision, that the defendant make restitution in accordance with sections 3663 and 3663A, or any other statute authorizing a sentence of restitution, and that the defendant not unlawfully possess a controlled substance. The court shall order as an explicit condition of supervised release for a defendant convicted for the first time of a domestic violence crime as defined in section 3561(b) that the defendant attend a public, private, or private nonprofit offender rehabilitation program that has been approved by the court, in consultation with a State Coalition Against Domestic Violence or other appropriate experts, if an approved program is readily available within a 50-mile radius of the legal residence of the defendant. The court shall order, as an explicit condition of supervised release for a person required to register under the Sex Offender Registration and Notification Act, that the person comply with the requirements of that Act. The court shall order, as an explicit condition of supervised release, that the defendant cooperate in the collection of a DNA sample from the defendant, if the collection of such a sample is authorized pursuant to section 3 of the DNA Analysis Backlog Elimination Act of 2000. The court shall also order, as an explicit condition of supervised release, that the defendant refrain from any unlawful use of a controlled substance and submit to a drug test within 15 days of release on supervised release and at least 2 periodic drug tests thereafter (as determined by the court) for use of a controlled substance. The condition stated in the preceding sentence may be ameliorated or suspended by the court as provided in section 3563(a)(4).1 The results of a drug test administered in accordance with the preceding subsection shall be subject to confirmation only if the results are positive, the defendant is subject to possible imprisonment for such failure, and either the defendant denies the accuracy of such test or there is some other reason to question the results of the test. A drug test confirmation shall be a urine drug test confirmed using gas chromatography/mass spectrometry techniques or such test as the Director of the Administrative Office of the United States Courts after consultation with the Secretary of Health and Human Services may determine to be of equivalent accuracy. The court shall consider whether the availability of appropriate substance abuse treatment programs, or an individual's current or past participation in such programs, warrants an exception in accordance with United States Sentencing Commission guidelines from the rule of section 3583(g) when considering any action against a defendant who fails a drug test. The court may order, as a further condition of supervised release, to the extent that such condition—"],[1,"(1) is reasonably related to the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), and (a)(2)(D);"],[1,"(2) involves no greater deprivation of liberty than is reasonably necessary for the purposes set forth in section 3553(a)(2)(B), (a)(2)(C), and (a)(2)(D); and"],[1,"(3) is consistent with any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a);"],[0,"any condition set forth as a discretionary condition of probation in section 3563(b) and any other condition it considers to be appropriate, provided, however that a condition set forth in subsection 3563(b)(10) shall be imposed only for a violation of a condition of supervised release in accordance with section 3583(e)(2) and only when facilities are available. If an alien defendant is subject to deportation, the court may provide, as a condition of supervised release, that he be deported and remain outside the United States, and may order that he be delivered to a duly authorized immigration official for such deportation. The court may order, as an explicit condition of supervised release for a person who is a felon and required to register under the Sex Offender Registration and Notification Act, that the person submit his person, and any property, house, residence, vehicle, papers, computer, other electronic communications or data storage devices or media, and effects to search at any time, with or without a warrant, by any law enforcement or probation officer with reasonable suspicion concerning a violation of a condition of supervised release or unlawful conduct by the person, and by any probation officer in the lawful discharge of the officer's supervision functions."],[0,"(e) Modification of Conditions or Revocation.—The court may, after considering the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)—"],[1,"(1) terminate a term of supervised release and discharge the defendant released at any time after the expiration of one year of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation, if it is satisfied that such action is warranted by the conduct of the defendant released and the interest of justice;"],[1,"(2) extend a term of supervised release if less than the maximum authorized term was previously imposed, and may modify, reduce, or enlarge the conditions of supervised release, at any time prior to the expiration or termination of the term of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation and the provisions applicable to the initial setting of the terms and conditions of post-release supervision;"],[1,"(3) revoke a term of supervised release, and require the defendant to serve in prison all or part of the term of supervised release authorized by statute for the offense that resulted in such term of supervised release without credit for time previously served on postrelease supervision, if the court, pursuant to the Federal Rules of Criminal Procedure applicable to revocation of probation or supervised release, finds by a preponderance of the evidence that the defendant violated a condition of supervised release, except that a defendant whose term is revoked under this paragraph may not be required to serve on any such revocation more than 5 years in prison if the offense that resulted in the term of supervised release is a class A felony, more than 3 years in prison if such offense is a class B felony, more than 2 years in prison if such offense is a class C or D felony, or more than one year in any other case; or"],[1,"(4) order the defendant to remain at his place of residence during nonworking hours and, if the court so directs, to have compliance monitored by telephone or electronic signaling devices, except that an order under this paragraph may be imposed only as an alternative to incarceration."],[0,"(f) Written Statement of Conditions.—The court shall direct that the probation officer provide the defendant with a written statement that sets forth all the conditions to which the term of supervised release is subject, and that is sufficiently clear and specific to serve as a guide for the defendant's conduct and for such supervision as is required."],[0,"(g) Mandatory Revocation for Possession of Controlled Substance or Firearm or for Refusal To Comply With Drug Testing.—If the defendant—"],[1,"(1) possesses a controlled substance in violation of the condition set forth in subsection (d);"],[1,"(2) possesses a firearm, as such term is defined in section 921 of this title, in violation of Federal law, or otherwise violates a condition of supervised release prohibiting the defendant from possessing a firearm;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3583?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 5, 19, 19, 19, 19, 5, 42, 5, 16, 22-23, 42, 45, 5, 5, 45, 5, 11, 16, 18, 26, 45, 17, 6, 19, 6-7, 21-22, 32, 41, 46, 49, 5, 5","1":"21, 21, 21, 21, 21, 21, 21, 21, 21, 21, 21","2":"11-13, 12, 1, 11-12, 4, 12, 10, 15, 24"},"q":[{"src":"brief","b":0,"text":"extend[] beyond the expiration of the term of supervised release.","cite":"18 U.S.C. § 3583(i)"},{"src":"brief","b":0,"text":"extends beyond the expiration of the term of supervised release.","cite":"18 U.S.C. § 3583(i)"},{"src":"brief","b":1,"text":"at any time after the expiration of one year of supervised release,","cite":"18 U.S.C. 3583(e)(1)"},{"src":"brief","b":1,"text":"absconding itself is a violation of supervised release that can result in revocation.","cite":"18 U.S.C. 3583(e)(3)"}]},{"t":"usc","label":"18 U.S.C. § 3624","url":"https://www.law.cornell.edu/uscode/text/18/3624","subs":["(e)"],"stext":{"head":"§3624. Release of a prisoner","paras":[[0,"(a) Date of Release.—A prisoner shall be released by the Bureau of Prisons on the date of the expiration of the prisoner's term of imprisonment, less any time credited toward the service of the prisoner's sentence as provided in subsection (b). If the date for a prisoner's release falls on a Saturday, a Sunday, or a legal holiday at the place of confinement, the prisoner may be released by the Bureau on the last preceding weekday."],[0,"(b) Credit Toward Service of Sentence for Satisfactory Behavior.—(1) Subject to paragraph (2), a prisoner who is serving a term of imprisonment of more than 1 year 1 other than a term of imprisonment for the duration of the prisoner's life, may receive credit toward the service of the prisoner's sentence of up to 54 days for each year of the prisoner's sentence imposed by the court, subject to determination by the Bureau of Prisons that, during that year, the prisoner has displayed exemplary compliance with institutional disciplinary regulations. Subject to paragraph (2), if the Bureau determines that, during that year, the prisoner has not satisfactorily complied with such institutional regulations, the prisoner shall receive no such credit toward service of the prisoner's sentence or shall receive such lesser credit as the Bureau determines to be appropriate. In awarding credit under this section, the Bureau shall consider whether the prisoner, during the relevant period, has earned, or is making satisfactory progress toward earning, a high school diploma or an equivalent degree. Credit that has not been earned may not later be granted. Subject to paragraph (2), credit for the last year of a term of imprisonment shall be credited on the first day of the last year of the term of imprisonment."],[0,"(2) Notwithstanding any other law, credit awarded under this subsection after the date of enactment of the Prison Litigation Reform Act shall vest on the date the prisoner is released from custody."],[0,"(3) The Attorney General shall ensure that the Bureau of Prisons has in effect an optional General Educational Development program for inmates who have not earned a high school diploma or its equivalent."],[0,"(4) Exemptions to the General Educational Development requirement may be made as deemed appropriate by the Director of the Federal Bureau of Prisons."],[0,"(c) Prerelease Custody.—"],[1,"(1) In general.—The Director of the Bureau of Prisons shall, to the extent practicable, ensure that a prisoner serving a term of imprisonment spends a portion of the final months of that term (not to exceed 12 months), under conditions that will afford that prisoner a reasonable opportunity to adjust to and prepare for the reentry of that prisoner into the community. Such conditions may include a community correctional facility."],[1,"(2) Home confinement authority.—The authority under this subsection may be used to place a prisoner in home confinement for the shorter of 10 percent of the term of imprisonment of that prisoner or 6 months. The Bureau of Prisons shall, to the extent practicable, place prisoners with lower risk levels and lower needs on home confinement for the maximum amount of time permitted under this paragraph."],[1,"(3) Assistance.—The United States Probation System shall, to the extent practicable, offer assistance to a prisoner during prerelease custody under this subsection."],[1,"(4) No limitations.—Nothing in this subsection shall be construed to limit or restrict the authority of the Director of the Bureau of Prisons under section 3621."],[1,"(5) Reporting.—Not later than 1 year after the date of the enactment of the Second Chance Act of 2007 (and every year thereafter), the Director of the Bureau of Prisons shall transmit to the Committee on the Judiciary of the Senate and the Committee on the Judiciary of the House of Representatives a report describing the Bureau's utilization of community corrections facilities. Each report under this paragraph shall set forth the number and percentage of Federal prisoners placed in community corrections facilities during the preceding year, the average length of such placements, trends in such utilization, the reasons some prisoners are not placed in community corrections facilities, and number of prisoners not being placed in community corrections facilities for each reason set forth, and any other information that may be useful to the committees in determining if the Bureau is utilizing community corrections facilities in an effective manner."],[1,"(6) Issuance of regulations.—The Director of the Bureau of Prisons shall issue regulations pursuant to this subsection not later than 90 days after the date of the enactment of the Second Chance Reauthorization Act of 2018, which shall ensure that placement in a community correctional facility by the Bureau of Prisons is—"],[2,"(A) conducted in a manner consistent with section 3621(b) of this title;"],[2,"(B) determined on an individual basis; and"],[2,"(C) of sufficient duration to provide the greatest likelihood of successful reintegration into the community."],[0,"(d) Allotment of Clothing, Funds, and Transportation.—Upon the release of a prisoner on the expiration of the prisoner's term of imprisonment, the Bureau of Prisons shall furnish the prisoner with—"],[1,"(1) suitable clothing;"],[1,"(2) an amount of money, not more than $500, determined by the Director to be consistent with the needs of the offender and the public interest, unless the Director determines that the financial position of the offender is such that no sum should be furnished; and"],[1,"(3) transportation to the place of the prisoner's conviction, to the prisoner's bona fide residence within the United States, or to such other place within the United States as may be authorized by the Director."],[0,"(e) Supervision After Release.—A prisoner whose sentence includes a term of supervised release after imprisonment shall be released by the Bureau of Prisons to the supervision of a probation officer who shall, during the term imposed, supervise the person released to the degree warranted by the conditions specified by the sentencing court. The term of supervised release commences on the day the person is released from imprisonment and runs concurrently with any Federal, State, or local term of probation or supervised release or parole for another offense to which the person is subject or becomes subject during the term of supervised release. A term of supervised release does not run during any period in which the person is imprisoned in connection with a conviction for a Federal, State, or local crime unless the imprisonment is for a period of less than 30 consecutive days. Upon the release of a prisoner by the Bureau of Prisons to supervised release, the Bureau of Prisons shall notify such prisoner, verbally and in writing, of the requirement that the prisoner adhere to an installment schedule, not to exceed 2 years except in special circumstances, to pay for any fine imposed for the offense committed by such prisoner, and of the consequences of failure to pay such fines under sections 3611 through 3614 of this title."],[0,"(f) Mandatory Functional Literacy Requirement.—"],[1,"(1) The Attorney General shall direct the Bureau of Prisons to have in effect a mandatory functional literacy program for all mentally capable inmates who are not functionally literate in each Federal correctional institution within 6 months from the date of the enactment of this Act."],[1,"(2) Each mandatory functional literacy program shall include a requirement that each inmate participate in such program for a mandatory period sufficient to provide the inmate with an adequate opportunity to achieve functional literacy, and appropriate incentives which lead to successful completion of such programs shall be developed and implemented."],[1,"(3) As used in this section, the term \"functional literacy\" means—"],[2,"(A) an eighth grade equivalence in reading and mathematics on a nationally recognized standardized test;"],[2,"(B) functional competency or literacy on a nationally recognized criterion-referenced test; or"],[2,"(C) a combination of subparagraphs (A) and (B)."],[1,"(4) Non-English speaking inmates shall be required to participate in an English-As-A-Second-Language program until they function at the equivalence of the eighth grade on a nationally recognized educational achievement test."],[1,"(5) The Chief Executive Officer of each institution shall have authority to grant waivers for good cause as determined and documented on an individual basis."],[0,"(g) Prerelease Custody or Supervised Release for Risk and Needs Assessment System Participants.—"],[1,"(1) Eligible prisoners.—This subsection applies in the case of a prisoner (as such term is defined in section 3635) who—"],[2,"(A) has earned time credits under the risk and needs assessment system developed under subchapter D (referred to in this subsection as the \"System\") in an amount that is equal to the remainder of the prisoner's imposed term of imprisonment;"],[2,"(B) has shown through the periodic risk reassessments a demonstrated recidivism risk reduction or has maintained a minimum or low recidivism risk, during the prisoner's term of imprisonment;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3624?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 6, 20, 26, 32","1":"40-42","2":"6-9, 14, 19"},"q":[{"src":"brief","b":1,"text":"released by the Bureau of Prisons to the supervision of a probation officer,","cite":"18 U.S.C. 3624(e)"},{"src":"brief","b":1,"text":"the supervision of [her] probation officer,","cite":"18 U.S.C. 3624(e)"},{"src":"argument","who":"Mr. Unikowsky","text":"It just seems more likely from our perspective that Congress intended the regime to operate this way: the clock keeps going unless it's tolled under the explicit language of Section 3624 or until there's a revocation hearing."}]},{"t":"usc","label":"18 U.S.C. § 3653","url":"https://www.law.cornell.edu/uscode/text/18/3653","by":{"0":"40"}},{"t":"usc","label":"18 U.S.C. § 4205","url":"https://www.law.cornell.edu/uscode/text/18/4205","by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"within the maximum term or terms for which he was sentenced.","cite":"18 U.S.C. § 4205"}]},{"t":"usc","label":"18 U.S.C. § 4210","url":"https://www.law.cornell.edu/uscode/text/18/4210","subs":["(b)","(b)(2)","(c)","(c)(1976)"],"by":{"0":"29, 37, 28, 31-32, 28-29, 31-32, 37, 41","1":"40-42","2":"15, 13-14, 13-15"},"q":[{"src":"brief","b":0,"text":"the jurisdiction of the Commission may be extended for the period during which the parolee so refused or failed to respond.","cite":"18 U.S.C. § 4210(c)"},{"src":"brief","b":0,"text":"whether all or any part of the unexpired term being served at the time of parole shall run concurrently or consecutively with the sentence imposed for the new offense.","cite":"18 U.S.C. § 4210(b)(2)"}]},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"3"}},{"t":"law","label":"Pub. L. No. 118-83","url":"https://www.govinfo.gov/link/plaw/118/public/83","by":{"0":"30"}},{"t":"law","label":"xii Parole Commission and Reorganization Act, Pub. L. No. 94-233","url":"https://www.govinfo.gov/link/statute/90/219","by":{"0":"28"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1987","by":{"0":"4, 32"}},{"t":"law","label":"Pub. L. No. 103-322","url":"https://www.govinfo.gov/link/statute/108/1796","by":{"0":"7","1":"41"}},{"t":"reg","label":"28 C.F.R. § 2.10","url":"https://www.ecfr.gov/current/title-28/section-2.10","subs":["(c)"],"by":{"0":"38"}},{"t":"reg","label":"28 C.F.R. § 2.40","url":"https://www.ecfr.gov/current/title-28/section-2.40","subs":["(e)"],"by":{"0":"30","2":"16"}},{"t":"reg","label":"28 C.F.R. § 2.52","url":"https://www.ecfr.gov/current/title-28/section-2.52","subs":["(c)","(c)(1)"],"by":{"0":"28, 30"}},{"t":"reg","label":"Paroling, Recommitting and Supervising Federal Prisoners, 41 Fed. Reg. 19,326","url":"https://www.govinfo.gov/link/fr/41/19326","by":{"0":"28"}},{"t":"reg","label":"Paroling, Recommitting, and Supervising Federal Prisoners, 48 Fed. Reg. 22,917","url":"https://www.govinfo.gov/link/fr/48/22917","by":{"0":"28-29, 37","1":"42","2":"13"}},{"t":"case","label":"Barber v. Thomas","cite":"560 U.S. 474","y":2010,"id":"2009/09-5201","sc":1,"by":{"1":"6"}},{"t":"case","label":"Barrier v. Beaver","cite":"712 F.2d 231","y":1983,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/712/231/","by":{"1":"41"},"q":[{"src":"brief","b":1,"text":"the statute, and regulations promulgated thereunder, merely provide the Parole Commission with the jurisdiction to hear and determine the allegation of violations contained within the warrant, even when, due to the fortuitous nearness of the parolee’s maximum term expiration, the hearing must be had after the Parole Commission’s authority to supervise the parolee’s conduct had terminated.","cite":"712 F.2d 231, 237"}]},{"t":"case","label":"Biddle v. Asher","cite":"295 F. 670","y":1924,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./295/670/","by":{"1":"27","2":"19"}},{"t":"case","label":"Black v. Romano","cite":"471 U.S. 606","y":1985,"id":"1984/84-465","sc":1,"by":{"1":"23"}},{"t":"case","label":"Dimmick v. Tompkins","cite":"194 U.S. 540","y":1904,"id":"scdb/1903-089","sc":1,"by":{"1":"26","2":"20"},"q":[{"src":"brief","b":1,"text":"any act * * * caused by his own conduct.","cite":"194 U.S. 540, 548-549"}]},{"t":"case","label":"Drinkall v. Spiegel","cite":"36 A. 830","y":1896,"court":"Conn.","url":"https://www.courtlistener.com/c/A./36/830/","by":{"1":"27","2":"20"}},{"t":"case","label":"Edmonds v. Compagnie Generale Transatlantique","cite":"443 U.S. 256","y":1979,"id":"1978/78-479","sc":1,"by":{"1":"30"}},{"t":"case","label":"Federal Bureau of Investigation v. Fazaga","cite":"595 U.S. 344","y":2022,"id":"2021/20-828","sc":1,"by":{"1":"35"}},{"t":"case","label":"Glus v. Brooklyn E. Dist. Terminal","cite":"359 U.S. 231","y":1959,"id":"1958/446","sc":1,"by":{"1":"4, 14, 44, 47"},"q":[{"src":"brief","b":1,"text":"take advantage of [her] own wrong,","cite":"359 U.S. 231, 232"},{"src":"brief","b":1,"text":"no man may take advantage of his own wrong,","cite":"359 U.S. 231, 232"}]},{"t":"case","label":"Hollon v. Hopkins","cite":"21 Kan. 638","y":1879,"url":"https://www.courtlistener.com/c/Kan./21/638/","by":{"1":"25, 26"}},{"t":"case","label":"Huddleston v. United States","cite":"415 U.S. 814","y":1974,"id":"1973/72-1076","sc":1,"by":{"1":"44"}},{"t":"case","label":"Luckey v. State","cite":"14 Tex. 400","y":1855,"url":"https://www.courtlistener.com/c/Tex./14/400/","by":{"1":"25"}},{"t":"case","label":"Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"by":{"1":"36"},"q":[{"src":"brief","b":1,"text":"The force of any negative implication, however, depends on context.","cite":"568 U.S. 371, 381"}]},{"t":"case","label":"Milhem v. United States","cite":"834 F.2d 118","y":1987,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/834/118/","by":{"1":"21"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"by":{"1":"6"},"q":[{"src":"brief","b":1,"text":"under the ‘guidance and control’ of a parole officer.","cite":"488 U.S. 361, 363"}]},{"t":"case","label":"Moody v. Daggett","cite":"429 U.S. 78","y":1976,"id":"1976/74-6632","sc":1,"by":{"1":"42"}},{"t":"case","label":"Nicolls v. Ingersoll","cite":"7 Johns. 145","y":1810,"court":"N.Y. Sup. Ct.","url":"https://www.courtlistener.com/c/Johns./7/145/","by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"a continuance of the former imprisonment.","cite":"7 Johns. 145, 155"}]},{"t":"case","label":"Pasquantino v. United States","cite":"544 U.S. 349","y":2005,"id":"2004/03-725","sc":1,"by":{"1":"29"}},{"t":"case","label":"Perttu v. Richards","cite":"605 U.S. 460","y":2025,"id":"2024/23-1324","sc":1,"by":{"1":"5, 14, 24, 29, 35"},"q":[{"src":"brief","b":1,"text":"is understood to legislate against a background of common-law adjudicatory principles,","cite":"605 U.S. 460, 461"},{"src":"brief","b":1,"text":"will apply except when a statutory purpose to the contrary is evident.","cite":"605 U.S. 460, 468"}]},{"t":"case","label":"Schwamble v. Sheriff","cite":"22 Pa. 18","y":1853,"url":"https://www.courtlistener.com/c/Pa./22/18/","by":{"1":"25"}},{"t":"case","label":"Shular v. United States","cite":"589 U.S. 154","y":2020,"id":"2019/18-6662","sc":1,"by":{"1":"44"}},{"t":"case","label":"United States v. Bestfoods","cite":"524 U.S. 51","y":1998,"id":"1997/97-454","sc":1,"by":{"1":"30"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"by":{"1":"44"},"q":[{"src":"brief","b":1,"text":"the rule of lenity only applies if, after considering text, structure, history, and purpose, there remains a grievous ambiguity or uncertainty in the statute, such that the Court must simply guess as to what Congress intended.","cite":"572 U.S. 157, 172-173"}]},{"t":"case","label":"United States v. Gerson","cite":"192 F. Supp. 864","y":1961,"court":"E.D. Tenn.","url":"https://www.courtlistener.com/c/F.%20Supp./192/864/","by":{"1":"31, 34","2":"19"}},{"t":"case","label":"United States v. Hamilton","cite":"986 F.3d 413","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/986/413/","by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"the district court and the probation officer work together * * * in the crafting and management of supervised release.","cite":"986 F.3d 413, 417-418"}]},{"t":"case","label":"United States v. Ignacio Juarez","cite":"601 F.3d 885","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/601/885/","by":{"1":"15, 43, 47"},"q":[{"src":"brief","b":1,"text":"ma[de] it impossible for the Probation Office to supervise h[er] actions,","cite":"601 F.3d 885, 890"},{"src":"brief","b":1,"text":"[f]ugitive tolling begins when the defendant absconds from supervision—making it impossible for the Probation Office to supervise his actions—and ends when federal authorities are capable of resuming supervision.","cite":"601 F.3d 885, 890"},{"src":"argument","who":"Mr. Handell","text":"Since then, they have clarified in Ignacio Juarez that it is actually a pattern of conduct that prevents supervision, that -- that precludes supervision, and I think that is fully consistent with what the Fifth Circuit said in Swick and the Fourth Circuit --"}]},{"t":"case","label":"United States v. Kebodeaux","cite":"570 U.S. 387","y":2013,"id":"2012/12-418","sc":1,"by":{"1":"6"}},{"t":"case","label":"United States v. Montenegro-Rojo","cite":"908 F.2d 425","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/908/425/","by":{"1":"6"},"q":[{"src":"brief","b":1,"text":"the anomalous situation could arise whereby a defendant in great need of postincarceration supervision would get little whereas a defendant who did not need such supervision would get a great deal.","cite":"908 F.2d 425, 433"}]},{"t":"case","label":"United States v. Pisano","cite":"266 F. Supp. 913","y":1967,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./266/913/","by":{"1":"31"}},{"t":"case","label":"United States v. Ribota","cite":"792 F.3d 837","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/792/837/","by":{"1":"21"}},{"t":"case","label":"United States v. Thompson","cite":"924 F.3d 122","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/924/122/","by":{"1":"15, 43, 44, 47"},"q":[{"src":"brief","b":1,"text":"violate[d] a condition of supervised release.","cite":"924 F.3d 122, 129"},{"src":"brief","b":1,"text":"[a] defendant does not become a fugitive for tolling purposes by virtue of missing a meeting with a probation officer, or simply because he violates a condition of supervised release.","cite":"924 F.3d 122, 129"}]},{"t":"case","label":"United States v. Watson","cite":"633 F.3d 929","y":2011,"url":"https://www.courtlistener.com/c/F.3d/633/929/","by":{"1":"47"}},{"t":"case","label":"United States v. Workman","cite":"617 F.2d 48","y":1980,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/617/48/","by":{"1":"29","2":"21"},"q":[{"src":"brief","b":1,"text":"for any period of time during which [the pro- bationer] was not, in fact, under probationary supervision by virtue of his own wrongful act.","cite":"617 F.2d 48, 51"}]},{"t":"usc","label":"18 U.S.C. § 3161","url":"https://www.law.cornell.edu/uscode/text/18/3161","subs":["(h)(3)"],"by":{"1":"21, 21"}},{"t":"usc","label":"18 U.S.C. § 3148","url":"https://www.law.cornell.edu/uscode/text/18/3148","by":{"1":"21"}},{"t":"usc","label":"18 U.S.C. § 3601","url":"https://www.law.cornell.edu/uscode/text/18/3601","stext":{"head":"§3601. Supervision of probation","paras":[[0,"A person who has been sentenced to probation pursuant to the provisions of subchapter B of chapter 227, or placed on probation pursuant to the provisions of chapter 403, or placed on supervised release pursuant to the provisions of section 3583, shall, during the term imposed, be supervised by a probation officer to the degree warranted by the conditions specified by the sentencing court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3601?type=usc&year=mostrecent&link-type=html"},"by":{"1":"40-42","2":"6-8, 24"},"q":[{"src":"brief","b":1,"text":"shall, during the term imposed, be supervised by [her] probation officer,","cite":"18 U.S.C. 3601"},{"src":"brief","b":1,"text":"be[ing] supervised by [her] probation officer.","cite":"18 U.S.C. 3601"},{"src":"argument","who":"Mr. Unikowsky","text":"I want to say a word about Section 3601, the statute that says that the supervisee shall be supervised, which counsel characterized as getting the government 98 percent there to the two yard line."}]},{"t":"usc","label":"18 U.S.C. § 3603","url":"https://www.law.cornell.edu/uscode/text/18/3603","subs":["(1)","(2)","(3)"],"by":{"1":"40-42, 40-42, 40-42, 40-42"},"q":[{"src":"brief","b":1,"text":"to bring about improvements in h[er] conduct and condition,","cite":"18 U.S.C. 3603(3)"},{"src":"brief","b":1,"text":"conduct and condition of * * * a person on supervised release, who is under his supervision, and report his conduct and condition to the sentencing court.","cite":"18 U.S.C. 3603(2)"}]},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(b)(1)(B)","(b)(1)(C)"],"by":{"1":"59, 59"}},{"t":"usc","label":"21 U.S.C. § 846","url":"https://www.law.cornell.edu/uscode/text/21/846","by":{"1":"59"}},{"t":"case","label":"Anderson v. Alexander (In re Anderson)","cite":"230 P.2d 770","y":1951,"court":"Or.","url":"https://www.courtlistener.com/c/P.2d/230/770/","by":{"2":"19"}},{"t":"case","label":"Central Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"by":{"2":"17"}},{"t":"case","label":"Stanley v. City of Sanford","cite":"606 U.S. 46","y":2025,"id":"2024/23-997","sc":1,"by":{"2":"9"},"q":[{"src":"brief","b":2,"text":"[N]o statute yet known pursues its stated purpose at all costs,","cite":"606 U.S. 46, 58"}]},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","by":{"2":"17"}}]};